 write(D/'final_verification.json',proof);write(D/'FROZEN.json',{'frozen':True,'files':{p.name:sha(p.read_bytes())for p in sorted(D.iterdir())if p.is_file()and p.name!='FROZEN.json'},'candidate_sha256':FINAL,'parent_arc_sha256':PARENT,'source_lock_sha256':sha((D/'SOURCE_LOCK.json').read_bytes()),'selected_visual_refs':list(REFS),'native_and_independent_passed':True,'root_packed_partial_ordered_reviewed':True,'supersedes_initial_pending_flags':True,'gameplay_verified':False,'user_accepted':False,'full_style_unification_complete':False});print(json.dumps({'frozen':ev(D/'FROZEN.json'),'final_verification':ev(D/'final_verification.json'),'candidate':FINAL}))
